#include "tscc/CompilationUnit.h"
#include <cstdlib>
#include <iostream>
using namespace tscc;static void fail(const char*m){std::cerr<<m<<'\n';std::exit(1);}static SourceFile source(std::string text){SourceFile s{"expressions.ts",std::move(text),{0}};for(std::size_t i=0;i<s.text.size();++i)if(s.text[i]=='\n')s.line_starts.push_back(i+1);return s;}
int main(){CompilationUnit unit(source("interface Box { value:number }\nconst box:Box={value:1};\nconst selected:number=true ? box?.value! : 2;\nlet count:number=0; count++;\nconst ok:number=(selected + count) satisfies number;\nif (selected >= 1 && count === 1) { count += 1; }\n"));if(!unit.analyze())fail("selected expression grammar did not check");bool conditional=false,optional=false,non_null=false,update=false,satisfies=false,condition_root=false,standalone_root=false;for(const auto&node:unit.expressions.nodes()){conditional|=node.kind==ExpressionKind::Conditional;optional|=node.kind==ExpressionKind::OptionalProperty;non_null|=node.kind==ExpressionKind::NonNull;update|=node.kind==ExpressionKind::Update;satisfies|=node.kind==ExpressionKind::Satisfies;}for(const auto&node:unit.semantic.nodes){if(node.id==InvalidSemanticNodeId)fail("semantic identity missing");if((node.kind==SemanticNodeKind::ExpressionRoot||node.kind==SemanticNodeKind::Condition)&&node.expression_id==InvalidExpressionId)fail("owned expression identity missing");condition_root|=node.kind==SemanticNodeKind::Condition;standalone_root|=node.kind==SemanticNodeKind::ExpressionRoot&&unit.tokens[node.begin_token].text=="count";}if(!conditional||!optional||!non_null||!update||!satisfies||!condition_root||!standalone_root)fail("selected grammar/ownership coverage missing");std::cout<<"complete selected expression ownership passed\n";}
